with cleaned as (select id, order_id, carrier, delivered_date, cost, status, last_day(delivered_date) as delivered_date_month_end from shipments where shipped_date > date '2023-09-01' and order_id is not null) select case when cost >= 74 then 'HIGH' else 'LOW' end as cost_tier, count(*) as cnt, sort_array(collect_set(carrier)) as carrier_list, count_if(status = 'DELIVERED') as delivered_events from cleaned group by case when cost >= 74 then 'HIGH' else 'LOW' end
